@tniessen am I right if we should add this check before calling [checkPathsSync()](https://github.com/nodejs/node/blob/7e0097d8a33fa7adbc1f298cbf647f6d2fd403e8/lib/internal/fs/cp/cp-sync.js#L287-L289)?

```
if (opts.filter && !opts.filter(srcItem, destItem)) continue;
```

And since the [startCopy](https://github.com/nodejs/node/blob/7e0097d8a33fa7adbc1f298cbf647f6d2fd403e8/lib/internal/fs/cp/cp-sync.js#L161-L164) has 2 lines and one of them is the filter call, should we move its main logic to [copyDir](https://github.com/nodejs/node/blob/7e0097d8a33fa7adbc1f298cbf647f6d2fd403e8/lib/internal/fs/cp/cp-sync.js#L277) and remove this function? Overall, the copyDir will look like this:

```
function copyDir(src, dest, opts) {
  const dir = opendirSync(src);

  try {
    let dirent;

    while ((dirent = dir.readSync()) !== null) {
      const { name } = dirent;
      const srcItem = join(src, name);
      const destItem = join(dest, name);
      if (opts.filter && !opts.filter(srcItem, destItem)) continue;
      const { destStat } = checkPathsSync(srcItem, destItem, opts);
      getStats(destStat, srcItem, destItem, opts);
    }
  } finally {
    dir.closeSync();
  }
}
```
